vec2 random2(vec2 p) {
    return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;

    uv *= 4.0;

    vec2 i_pos = floor(uv);
    vec2 f_pos = fract(uv);

    vec3 outer_color = vec3(0.96, 0.86, 0.71); // Approx #FAD6B0
    vec3 nucleus_color = vec3(0.8, 0.1, 0.2); // Approx #CC1933

    float m_dist = 1.0;
    vec3 color;

    for (int y = -1; y <= 1; y++)
    {
        for (int x = -1; x <= 1; x++)
        {
            vec2 neighbour = vec2(float(x), float(y));

            vec2 point = random2(i_pos + neighbour);

            point = 0.5 + 0.5 * sin(0.2 * iTime * 6.28 * point);
            float dist = length(point + neighbour - f_pos);
            m_dist = min(dist, m_dist);
        }
    }
    color = mix(nucleus_color, outer_color, m_dist);
    color += 1.0 - step(0.015, m_dist);

    fragColor = vec4(color, 1.0);
}
